namespace ContosoDashboard.Services;

/// <summary>Private local storage boundary. Keys are generated by the service and are not paths.</summary>
public interface IFileStorageService
{
    Task<string> StageAsync(Stream content, CancellationToken cancellationToken = default);
    Task<Stream> OpenQuarantineReadAsync(string quarantineKey, CancellationToken cancellationToken = default);
    Task<string> PublishAsync(string quarantineKey, CancellationToken cancellationToken = default);
    Task<Stream> OpenReadAsync(string storageKey, CancellationToken cancellationToken = default);
    Task DeleteQuarantineAsync(string quarantineKey, CancellationToken cancellationToken = default);
    Task DeletePublishedAsync(string storageKey, CancellationToken cancellationToken = default);
}
